# CASO-LIM-023 · retry solo timeout/429
def should_retry(k):
    # Arregla: reintenta captcha también
    return k in {'timeout', '429', 'captcha'}

for k in ['timeout','captcha','429']:
    print(k, should_retry(k))

# CASO-LIM-023 · recovery stale vs. timeout
# Arregla: stale devuelve continue
def recover(err):
    if err == 'stale':
        return 'continue'
    if err == 'timeout':
        return 'retry'
    return 'continue'

print(recover('stale'))
print(recover('timeout'))

# CASO-LIM-023 · api first (jerarquía)
# Arregla: evalúa rpa antes que api (orden invertido)
caps = {'api': True, 'export': True, 'rpa': True}
if caps.get('rpa'):
    print('rpa')
elif caps.get('export'):
    print('export')
elif caps.get('api'):
    print('api')
else:
    print('human')

